public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0) return "cannot be travelled";
        if (start == null || end == null) return "cannot be travelled";
        if (start.length != n || end.length != n) return "cannot be travelled";

        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

        String startKey = java.util.Arrays.toString(start);
        String endKey = java.util.Arrays.toString(end);
        graph.putIfAbsent(startKey, new java.util.ArrayList<>());
        graph.putIfAbsent(endKey, new java.util.ArrayList<>());

        if (paths != null) {
            for (int[] path : paths) {
                if (path == null || path.length != 2 * n) continue;
                int[] from = new int[n];
                int[] to = new int[n];
                System.arraycopy(path, 0, from, 0, n);
                System.arraycopy(path, n, to, 0, n);
                String fromKey = java.util.Arrays.toString(from);
                String toKey = java.util.Arrays.toString(to);
                graph.putIfAbsent(fromKey, new java.util.ArrayList<>());
                graph.putIfAbsent(toKey, new java.util.ArrayList<>());
                graph.get(fromKey).add(toKey);
                graph.get(toKey).add(fromKey);
            }
        }

        if (startKey.equals(endKey)) return "can be travelled";

        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        queue.add(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            for (String neigh : graph.getOrDefault(cur, java.util.Collections.emptyList())) {
                if (!visited.contains(neigh)) {
                    if (neigh.equals(endKey)) return "can be travelled";
                    visited.add(neigh);
                    queue.add(neigh);
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

