    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        int u = edge[0];
        int v = edge[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    boolean[] visited = new boolean[n];
    int[] totalTime = new int[1]; // use array to allow modification inside helper

    // Helper DFS that returns whether the subtree rooted at 'node' contains an apple
    java.util.function.Function<Integer, Boolean> dfs = new java.util.function.Function<Integer, Boolean>() {
